sql.where:
AND (
    1 = 0

        OR (source_type = 'FAMILY' AND creator_user_id = #{query.currentUserId})


        OR (source_type = 'TEACHER' AND creator_user_id = #{query.currentUserId})


        OR (source_type = 'ORGANIZATION' AND EXISTS (
            SELECT 1
            FROM sys_organization task_source_organization
            JOIN sys_organization administrator_root
              ON task_source_organization.organization_path
                 LIKE CONCAT(administrator_root.organization_path, '%')
            JOIN sys_organization_admin organization_admin
              ON organization_admin.organization_id = administrator_root.id
            WHERE task_source_organization.id = learn_task.source_organization_id
              AND organization_admin.user_id = #{query.currentUserId}
        ))

)

    AND source_type = #{query.sourceType}


    AND status = #{query.status}


    AND scheduled_date = #{query.scheduledDate}


    AND title LIKE CONCAT('%', #{query.keyword}, '%')

mapper.select:
SELECT  FROM learn_task

ORDER BY scheduled_date DESC, created_at DESC, id DESC
LIMIT #{query.limit} OFFSET #{query.offset}
